        return now > startTime || remainingTokens == 0;
    }

    function ended() public view returns(bool) {
        return now > endTime || remainingTokens == 0;
    }

    function startTime() public view returns(uint) {
        return startTime;
    }

    function endTime() public view returns(uint) {
        return endTime;
    }

